/// <summary>
///
/// </summary>
public void callAPI()
{
    XAPI_APILogTable lotTable;
    Map configMap = new Map(Types::String, Types::String);

    configMap.insert('<DataAreaId>', curExt());

    select firstonly lotTable
        where lotTable.ApiName == XAPI_APIS::CreateCustomer
        && lotTable.Key == 'CustAccount';

    configMap.insert('<custAccount>', lotTable.Value);

    select firstonly lotTable
    where lotTable.ApiName == XAPI_APIS::CreateContract
       && lotTable.Key == 'ContractNum';
    configMap.insert('<Contract>', lotTable.Value);

    select firstonly  lotTable
    where lotTable.ApiName == XAPI_APIS::CreateInstallation
        && lotTable.Key == 'InstNum';
    configMap.insert('<InstNum>', lotTable.Value);

    EXU_UtilityInstallation uinst;
    select firstonly uinst
        where uinst.InstNum == lotTable.Value;

    configMap.insert('<deliveryCategory>', uinst.DeliveryCategory);

    this.prepareBody(configMap);
    this.sendPostRequest();

    EGS_API_DataContract_Response res =FormJsonSerializer::deserializeObject(classNum(EGS_API_DataContract_Response), responseText);

    this.log("ContractPartNum", res.parmMessage());

    EGS_MASS_ImportContractExt contractExt = EGS_MASS_ImportContractExt::construct();
    contractExt.run();
}
